{
  "root": "main_stack",
  "state": {
    "productSales": [
      {
        "Product": "Laptop",
        "Total Sales": 45000
      },
      {
        "Product": "Monitor",
        "Total Sales": 27000
      },
      {
        "Product": "Keyboard",
        "Total Sales": 15700
      },
      {
        "Product": "Mouse",
        "Total Sales": 10500
      }
    ],
    "monthlySales": [
      {
        "Month": "January",
        "Total Sales": 28000
      },
      {
        "Month": "February",
        "Total Sales": 32700
      },
      {
        "Month": "March",
        "Total Sales": 37500
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h1",
        "intro_text",
        "product_sales_section",
        "monthly_sales_section",
        "quick_actions_section"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Q1 2023 Sales Performance Summary",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Here is a breakdown of your sales data for the first quarter of 2023, presented for visualization as requested.",
        "variant": "body"
      },
      "children": []
    },
    "product_sales_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "product_sales_header_stack",
        "product_sales_intro_text",
        "product_sales_table"
      ]
    },
    "product_sales_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": [
        "product_sales_icon",
        "product_sales_h2"
      ]
    },
    "product_sales_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000606_01_1_bar-chart-line.svg"
      },
      "children": []
    },
    "product_sales_h2": {
      "type": "Text",
      "props": {
        "text": "Product Sales Overview",
        "variant": "h2"
      },
      "children": []
    },
    "product_sales_intro_text": {
      "type": "Text",
      "props": {
        "text": "This table provides the total sales for each product during Q1 2023, suitable for generating a bar chart.",
        "variant": "body"
      },
      "children": []
    },
    "product_sales_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "Product",
            "label": "Product"
          },
          {
            "key": "Total Sales",
            "label": "Total Sales"
          }
        ],
        "statePath": "/productSales",
        "domain": "generic",
        "preferredPresentation": "table",
        "numericColumns": [
          "Total Sales"
        ]
      },
      "children": []
    },
    "monthly_sales_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "monthly_sales_header_stack",
        "monthly_sales_intro_text",
        "monthly_sales_table"
      ]
    },
    "monthly_sales_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": [
        "monthly_sales_icon",
        "monthly_sales_h2"
      ]
    },
    "monthly_sales_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000606_01_2_graph-up.svg"
      },
      "children": []
    },
    "monthly_sales_h2": {
      "type": "Text",
      "props": {
        "text": "Monthly Sales Trends",
        "variant": "h2"
      },
      "children": []
    },
    "monthly_sales_intro_text": {
      "type": "Text",
      "props": {
        "text": "This table shows the aggregated monthly sales across all products for Q1 2023, suitable for generating a line chart.",
        "variant": "body"
      },
      "children": []
    },
    "monthly_sales_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "Month",
            "label": "Month"
          },
          {
            "key": "Total Sales",
            "label": "Total Sales"
          }
        ],
        "statePath": "/monthlySales",
        "domain": "generic",
        "preferredPresentation": "table",
        "numericColumns": [
          "Total Sales"
        ]
      },
      "children": []
    },
    "quick_actions_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "quick_actions_h2",
        "export_button",
        "report_button"
      ]
    },
    "quick_actions_h2": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "export_button": {
      "type": "Button",
      "props": {
        "label": "Export Data"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.com/export_sales_data"
          }
        }
      },
      "children": []
    },
    "report_button": {
      "type": "Button",
      "props": {
        "label": "View Full Report"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.com/q1_2023_sales_report"
          }
        }
      },
      "children": []
    }
  }
}
